#!/usr/bin/env python3
import os
import sys
import struct
import time
import math
import fnmatch
import shutil
import subprocess
from dataclasses import dataclass
from typing import List, Optional, Tuple, Dict

VERSION = "0.9.9"
AUTHOR = "Ajeet D'Souza <98ajeet@gmail.com>"
URL = "https://github.com/ajeetdsouza/zoxide"
ENV_HELP = """Environment variables:
  _ZO_DATA_DIR          Path for zoxide data files
  _ZO_ECHO              Print the matched directory before navigating to it when set to 1
  _ZO_EXCLUDE_DIRS      List of directory globs to be excluded
  _ZO_FZF_OPTS          Custom flags to pass to fzf
  _ZO_MAXAGE            Maximum total age after which entries start getting deleted
  _ZO_RESOLVE_SYMLINKS  Resolve symlinks when storing paths"""

SHELLS = ["bash", "elvish", "fish", "nushell", "posix", "powershell", "tcsh", "xonsh", "zsh"]
HOOKS = ["none", "prompt", "pwd"]

@dataclass
class Entry:
    path: str
    score: float
    last_accessed: int

class ZoxideError(Exception):
    pass

class CliExit(Exception):
    def __init__(self, code: int):
        self.code = code


def prog() -> str:
    return os.path.basename(sys.argv[0]) or "executable"


def out(s: str = "", end: str = "\n"):
    sys.stdout.write(s + end)


def err(s: str = "", end: str = "\n"):
    sys.stderr.write(s + end)


def runtime_error(message: str):
    err(f"zoxide: {message}")
    raise CliExit(1)


def os_error_text(e: OSError) -> str:
    if getattr(e, 'errno', None) is not None:
        return f"{e.strerror} (os error {e.errno})"
    return str(e)


def main_help() -> str:
    p = prog()
    return f"""zoxide {VERSION}
{AUTHOR}
{URL}

A smarter cd command for your terminal

Usage:
  {p} <COMMAND>

Commands:
  add     Add a new directory or increment its rank
  edit    Edit the database
  import  Import entries from another application
  init    Generate shell configuration
  query   Search for a directory in the database
  remove  Remove a directory from the database

Options:
  -h, --help     Print help
  -V, --version  Print version

{ENV_HELP}"""


def sub_help(cmd: str) -> str:
    p = prog()
    heads = {
        'add': ('zoxide-add', 'Add a new directory or increment its rank', f"{p} add [OPTIONS] <PATHS>...", "Arguments:\n  <PATHS>...  \n\nOptions:\n  -s, --score <SCORE>  The rank to increment the entry if it exists or initialize it with if it doesn't\n  -h, --help           Print help\n  -V, --version        Print version"),
        'edit': ('zoxide-edit', 'Edit the database', f"{p} edit", "Options:\n  -h, --help     Print help\n  -V, --version  Print version"),
        'import': ('zoxide-import', 'Import entries from another application', f"{p} import [OPTIONS] --from <FROM> <PATH>", "Arguments:\n  <PATH>  \n\nOptions:\n      --from <FROM>  Application to import from [possible values: autojump, z]\n      --merge        Merge into existing database\n  -h, --help         Print help\n  -V, --version      Print version"),
        'init': ('zoxide-init', 'Generate shell configuration', f"{p} init [OPTIONS] <SHELL>", "Arguments:\n  <SHELL>  [possible values: bash, elvish, fish, nushell, posix, powershell, tcsh, xonsh, zsh]\n\nOptions:\n      --no-cmd       Prevents zoxide from defining the `z` and `zi` commands\n      --cmd <CMD>    Changes the prefix of the `z` and `zi` commands [default: z]\n      --hook <HOOK>  Changes how often zoxide increments a directory's score [default: pwd] [possible values: none, prompt, pwd]\n  -h, --help         Print help\n  -V, --version      Print version"),
        'query': ('zoxide-query', 'Search for a directory in the database', f"{p} query [OPTIONS] [KEYWORDS]...", "Arguments:\n  [KEYWORDS]...  \n\nOptions:\n  -a, --all              Show unavailable directories\n  -i, --interactive      Use interactive selection\n  -l, --list             List all matching directories\n  -s, --score            Print score with results\n      --exclude <path>   Exclude the current directory\n      --base-dir <path>  Only search within this directory\n  -h, --help             Print help\n  -V, --version          Print version"),
        'remove': ('zoxide-remove', 'Remove a directory from the database', f"{p} remove [PATHS]...", "Arguments:\n  [PATHS]...  \n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version"),
    }
    name, desc, usage, body = heads[cmd]
    return f"""{name} {VERSION}
{AUTHOR}
{URL}

{desc}

Usage:
  {usage}

{body}

{ENV_HELP}"""


def cli_error(message: str, usage: Optional[str] = None, tip: Optional[str] = None, extra: Optional[str] = None):
    parts = [f"error: {message}"]
    if extra:
        parts.append(extra.rstrip("\n"))
    if tip:
        parts.append(f"  tip: {tip}")
    if usage:
        parts.append(f"Usage: {usage}")
    parts.append("For more information, try '--help'.")
    # clap puts a blank line between logical sections
    text = parts[0]
    idx = 1
    if extra:
        text += "\n" + parts[idx]; idx += 1
    if tip:
        text += "\n\n" + parts[idx]; idx += 1
    if usage:
        text += "\n\n" + parts[idx]; idx += 1
    text += "\n\n" + parts[idx]
    err(text)
    raise CliExit(2)


def unexpected(arg: str, usage: str, tip: Optional[str] = None):
    cli_error(f"unexpected argument '{arg}' found", usage=usage, tip=tip)


def possible_values(vals: List[str]) -> str:
    return "  [possible values: " + ", ".join(vals) + "]"


def data_dir() -> str:
    if '_ZO_DATA_DIR' in os.environ:
        d = os.environ.get('_ZO_DATA_DIR', '')
        if not os.path.isabs(d):
            raise ZoxideError("_ZO_DATA_DIR must be an absolute path")
        return d
    xdg = os.environ.get('XDG_DATA_HOME')
    if xdg:
        return os.path.join(xdg, 'zoxide')
    home = os.environ.get('HOME')
    if home:
        return os.path.join(home, '.local', 'share', 'zoxide')
    return os.path.join(os.path.expanduser('~'), '.local', 'share', 'zoxide')


def db_path() -> str:
    return os.path.join(data_dir(), 'db.zo')


def load_db() -> List[Entry]:
    path = db_path()
    try:
        with open(path, 'rb') as f:
            data = f.read()
    except FileNotFoundError:
        return []
    except OSError as e:
        raise ZoxideError(f"could not read from database: {path}\n\nCaused by:\n    {os_error_text(e)}")
    if len(data) < 12:
        raise ZoxideError("could not deserialize database: corrupted data")
    try:
        version = struct.unpack_from('<I', data, 0)[0]
        if version != 3:
            raise ZoxideError(f"unsupported version (got {version}, supports 3)")
        n = struct.unpack_from('<Q', data, 4)[0]
        off = 12
        entries: List[Entry] = []
        for _ in range(n):
            if off + 8 > len(data):
                raise EOFError
            l = struct.unpack_from('<Q', data, off)[0]; off += 8
            if off + l + 16 > len(data):
                raise EOFError
            pbytes = data[off:off+l]; off += l
            p = pbytes.decode('utf-8')
            score = struct.unpack_from('<d', data, off)[0]; off += 8
            ts = struct.unpack_from('<Q', data, off)[0]; off += 8
            entries.append(Entry(p, score, int(ts)))
        return entries
    except ZoxideError:
        raise
    except EOFError:
        raise ZoxideError("could not deserialize database\n\nCaused by:\n    io error: ")
    except Exception:
        raise ZoxideError("could not deserialize database: corrupted data")


def save_db(entries: List[Entry]):
    path = db_path()
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(struct.pack('<I', 3))
            f.write(struct.pack('<Q', len(entries)))
            for e in entries:
                b = e.path.encode('utf-8')
                f.write(struct.pack('<Q', len(b)))
                f.write(b)
                f.write(struct.pack('<d', float(e.score)))
                # clamp timestamp to unsigned range for packing
                ts = int(e.last_accessed)
                if ts < 0:
                    ts = 0
                f.write(struct.pack('<Q', ts))
    except OSError as e:
        raise ZoxideError(f"could not write to database: {path}\n\nCaused by:\n    {os_error_text(e)}")


def get_maxage() -> int:
    s = os.environ.get('_ZO_MAXAGE')
    if s is None:
        return 10000
    if not s.isdigit():
        raise ZoxideError(f"unable to parse _ZO_MAXAGE as integer: {s}\n\nCaused by:\n    invalid digit found in string")
    try:
        return int(s)
    except Exception:
        raise ZoxideError(f"unable to parse _ZO_MAXAGE as integer: {s}\n\nCaused by:\n    number too large to fit in target type")


def age_entries(entries: List[Entry]):
    maxage = get_maxage()
    # Rust's sum with NaN/inf semantics is well-enough approximated by Python.
    total = sum(e.score for e in entries)
    try:
        over = total > maxage
    except Exception:
        over = False
    if over:
        factor = 0.9 * maxage / total if total != 0 else 0.0
        for e in entries:
            e.score *= factor
        entries[:] = [e for e in entries if not (e.score < 1.0)]


def canonical_path(p: str) -> str:
    if os.environ.get('_ZO_RESOLVE_SYMLINKS') == '1':
        return os.path.realpath(p)
    return os.path.abspath(p)


def score_input_value(v: float) -> float:
    # Rust f64::max treats NaN as the other argument; max(score, 0.0)
    if math.isnan(v):
        return 0.0
    return v if v > 0.0 else 0.0


def excluded(path: str) -> bool:
    patterns = []
    home = os.environ.get('HOME')
    if home:
        patterns.append(home)
    val = os.environ.get('_ZO_EXCLUDE_DIRS')
    if val is not None and val != '':
        patterns.extend(val.split(':'))
    for pat in patterns:
        if pat and fnmatch.fnmatch(path, pat):
            return True
    return False


def db_map(entries: List[Entry]) -> Dict[str, Entry]:
    return {e.path: e for e in entries}


def now_ts() -> int:
    return int(time.time())


def add_paths(paths: List[str], score: float):
    # Validate all non-excluded paths before mutating the database.
    normalized: List[str] = []
    for p in paths:
        cp = canonical_path(p)
        if not os.path.isdir(cp):
            raise ZoxideError(f"not a directory: {cp}")
        if excluded(cp):
            continue
        normalized.append(cp)
    entries = load_db()
    m = db_map(entries)
    inc = score_input_value(score)
    ts = now_ts()
    for cp in normalized:
        if cp in m:
            m[cp].score += inc
            m[cp].last_accessed = ts
        else:
            e = Entry(cp, inc, ts)
            entries.append(e)
            m[cp] = e
    age_entries(entries)
    save_db(entries)


def remove_paths(paths: List[str]):
    if not paths:
        return
    entries = load_db()
    m = db_map(entries)
    normalized = [canonical_path(p) for p in paths]
    for raw, cp in zip(paths, normalized):
        if cp not in m:
            raise ZoxideError(f"path not found in database: {raw}")
    entries[:] = [e for e in entries if e.path not in set(normalized)]
    save_db(entries)


def frecency(e: Entry, now: Optional[int] = None) -> float:
    if now is None:
        now = now_ts()
    age = now - int(e.last_accessed)
    if age < 3600:
        mult = 4.0
    elif age < 86400:
        mult = 2.0
    elif age < 604800:
        mult = 0.5
    else:
        mult = 0.25
    val = e.score * mult
    if math.isnan(val):
        return val
    if val < 0.0:
        return 0.0
    if val > 9999.0 or math.isinf(val):
        return 9999.0
    return val


def format_score(v: float) -> str:
    if math.isnan(v):
        return "   NaN"
    # val should be clamped already, but keep this robust.
    if math.isinf(v):
        v = 9999.0 if v > 0 else 0.0
    if v < 0:
        v = 0.0
    if v > 9999.0:
        v = 9999.0
    return f"{v:6.1f}"


def path_available(path: str) -> bool:
    return os.path.isdir(path)


def in_base(path: str, base: Optional[str]) -> bool:
    if base is None:
        return True
    b = base
    # zoxide treats trailing slashes as insignificant for this filter (except root).
    while len(b) > 1 and b.endswith('/'):
        b = b[:-1]
    if b == '/':
        return path.startswith('/')
    return path == b or path.startswith(b + '/')


def path_matches(path: str, keywords: List[str]) -> bool:
    if not keywords:
        return True
    s = path.lower()
    kws = [k.lower() for k in keywords]
    start = 0
    # Empty final keyword can always be placed at the end if prior keywords matched.
    for i, k in enumerate(kws):
        final = (i == len(kws) - 1)
        if final:
            if k == '':
                return True
            pos = s.find(k, start)
            while pos != -1:
                end = pos + len(k)
                if '/' not in s[end:]:
                    return True
                pos = s.find(k, pos + 1)
            return False
        else:
            if k == '':
                # Empty non-final keyword consumes nothing.
                continue
            pos = s.find(k, start)
            if pos == -1:
                return False
            start = pos + len(k)
    return True


def ranked_entries(keywords: List[str], show_all: bool, exclude: Optional[str], base_dir: Optional[str]) -> Tuple[List[Tuple[Entry, float]], List[Tuple[Entry, float]]]:
    entries = load_db()
    now = now_ts()
    pairs: List[Tuple[Entry, float]] = []
    for e in entries:
        if not show_all and not path_available(e.path):
            continue
        if not in_base(e.path, base_dir):
            continue
        if not path_matches(e.path, keywords):
            continue
        pairs.append((e, frecency(e, now)))
    def sort_key(item):
        e, f = item
        # Rust's ordering around NaN is not total; put NaN first to match observed list enough.
        nan = 1 if math.isnan(f) else 0
        fv = 0.0 if math.isnan(f) else f
        return (nan, fv, e.last_accessed)
    pairs.sort(key=sort_key, reverse=True)
    before_exclude = list(pairs)
    if exclude is not None:
        pairs = [p for p in pairs if p[0].path != exclude]
    return pairs, before_exclude


def print_query_result(pair: Tuple[Entry, float], with_score: bool, terminator: str = '\n'):
    e, f = pair
    if with_score:
        sys.stdout.write(f"{format_score(f)} {e.path}{terminator}")
    else:
        sys.stdout.write(f"{e.path}{terminator}")


def query_cmd(keywords: List[str], show_all: bool, interactive: bool, list_mode: bool, with_score: bool, exclude: Optional[str], base_dir: Optional[str]):
    pairs, before = ranked_entries(keywords, show_all, exclude, base_dir)
    if list_mode:
        for pair in pairs:
            print_query_result(pair, with_score)
        return
    if interactive:
        interactive_query(pairs, with_score)
        return
    if pairs:
        print_query_result(pairs[0], with_score)
        return
    if exclude is not None and len(before) == 1 and before[0][0].path == exclude:
        raise ZoxideError("you are already in the only match")
    raise ZoxideError("no match found")


def fzf_path() -> Optional[str]:
    return shutil.which('fzf')


def fzf_preview_arg() -> str:
    return r"\command -p ls -Cp --color=always --group-directories-first {2..}"


def interactive_query(pairs: List[Tuple[Entry, float]], with_score: bool):
    fzf = fzf_path()
    if not fzf:
        raise ZoxideError("could not find fzf, is it installed?")
    data = b''.join((f"{format_score(f)}\t{e.path}".encode() + b'\0') for e, f in pairs)
    args = [fzf, "--delimiter=\t", "--nth=2", "--read0"]
    env = os.environ.copy()
    if '_ZO_FZF_OPTS' in os.environ:
        env['FZF_DEFAULT_OPTS'] = os.environ.get('_ZO_FZF_OPTS', '')
    else:
        args += [
            "--exact", "--no-sort", "--bind=ctrl-z:ignore,btab:up,tab:down",
            "--cycle", "--keep-right", "--border=sharp", "--height=45%",
            "--info=inline", "--layout=reverse", "--tabstop=1", "--exit-0",
            "--preview=" + fzf_preview_arg(), "--preview-window=down,30%,sharp",
        ]
    proc = subprocess.run(args, input=data, stdout=subprocess.PIPE, stderr=None, env=env)
    if proc.returncode == 130:
        raise CliExit(130)
    if proc.returncode != 0:
        raise ZoxideError("no match found")
    sel = proc.stdout
    if not sel:
        raise ZoxideError("could not read selection from fzf")
    if with_score:
        sys.stdout.buffer.write(sel)
    else:
        # The selected record starts with a fixed-width score and a tab (7 bytes).
        sys.stdout.buffer.write(sel[7:])


def output_reload():
    entries = load_db()
    now = now_ts()
    pairs = [(e, frecency(e, now)) for e in entries]
    pairs.sort(key=lambda item: ((1 if math.isnan(item[1]) else 0), 0.0 if math.isnan(item[1]) else item[1], item[0].last_accessed), reverse=True)
    for e, f in pairs:
        sys.stdout.buffer.write(f"{format_score(f)}\t{e.path}".encode() + b'\0')


def edit_hidden(op: str, paths: List[str]):
    entries = load_db()
    if op == 'reload':
        output_reload(); return
    if op == 'delete':
        rem = set(paths)
        entries = [e for e in entries if e.path not in rem]
        save_db(entries)
        output_reload(); return
    if op in ('increment', 'decrement'):
        m = db_map(entries)
        ts = now_ts()
        for p in paths:
            if p not in m:
                e = Entry(p, 0.0, ts)
                entries.append(e); m[p] = e
            e = m[p]
            if op == 'increment':
                e.score += 1.0
            else:
                e.score -= 1.0
                if math.isnan(e.score):
                    pass
                elif e.score < 0.0:
                    e.score = 0.0
            e.last_accessed = ts
        age_entries(entries)
        save_db(entries)
        output_reload(); return
    # should not get here


def edit_cmd(args: List[str]):
    if not args:
        fzf = fzf_path()
        if not fzf:
            raise ZoxideError("could not find fzf, is it installed?")
        fzf_args = [
            fzf, "--delimiter=\t", "--nth=2", "--read0", "--exact", "--no-sort",
            "--bind=btab:up,ctrl-r:reload(zoxide edit reload),ctrl-d:reload(zoxide edit delete {2..}),ctrl-w:reload(zoxide edit increment {2..}),ctrl-s:reload(zoxide edit decrement {2..}),ctrl-z:ignore,double-click:ignore,enter:abort,start:reload(zoxide edit reload),tab:down",
            "--cycle", "--keep-right", "--border=sharp", "--border-label=  zoxide-edit  ",
            "--header=ctrl-r:reload   \tctrl-d:delete\nctrl-w:increment\tctrl-s:decrement\n\n SCORE\tPATH",
            "--info=inline", "--layout=reverse", "--padding=1,0,0,0", "--color=label:bold", "--tabstop=1",
            "--preview=" + fzf_preview_arg(), "--preview-window=down,30%,sharp",
        ]
        proc = subprocess.run(fzf_args)
        if proc.returncode == 1:
            raise ZoxideError("no match found")
        raise CliExit(proc.returncode)
    if args[0] in ('reload', 'delete', 'increment', 'decrement'):
        edit_hidden(args[0], args[1:])
        return
    cli_error(f"unrecognized subcommand '{args[0]}'", usage=f"{prog()} edit")


def import_z(lines: List[str]) -> List[Entry]:
    m: Dict[str, Entry] = {}
    order: List[Entry] = []
    for line in lines:
        if line.endswith('\n'):
            line = line[:-1]
        if line.endswith('\r'):
            line = line[:-1]
        if line == '':
            continue
        parts = line.rsplit('|', 2)
        if len(parts) < 3:
            # zoxide reports an epoch parse error with the whole line.
            raise ZoxideError(f"import error\n\nCaused by:\n    0: invalid epoch: {line}\n    1: invalid digit found in string")
        path, rank_s, epoch_s = parts
        try:
            epoch = int(epoch_s)
        except Exception:
            raise ZoxideError(f"import error\n\nCaused by:\n    0: invalid epoch: {epoch_s}\n    1: invalid digit found in string")
        try:
            rank = float(rank_s)
        except Exception:
            raise ZoxideError(f"import error\n\nCaused by:\n    0: invalid rank: {rank_s}\n    1: invalid float literal")
        if path in m:
            m[path].score += rank
            if epoch > m[path].last_accessed:
                m[path].last_accessed = epoch
        else:
            e = Entry(path, rank, epoch)
            m[path] = e; order.append(e)
    return order


def import_autojump(lines: List[str]) -> List[Entry]:
    m: Dict[str, Entry] = {}
    order: List[Entry] = []
    for line in lines:
        if line.endswith('\n'):
            line = line[:-1]
        if line.endswith('\r'):
            line = line[:-1]
        if line == '':
            continue
        parts = line.split('\t')
        if len(parts) != 2:
            raise ZoxideError(f"import error\n\nCaused by:\n    invalid entry: {line}")
        rank_s, path = parts
        try:
            rank = float(rank_s)
        except Exception:
            raise ZoxideError(f"import error\n\nCaused by:\n    0: invalid rank: {rank_s}\n    1: invalid float literal")
        score = 1.0 - math.exp(-rank)
        if path in m:
            m[path].score += score
        else:
            e = Entry(path, score, 0)
            m[path] = e; order.append(e)
    return order


def import_cmd(from_app: str, merge: bool, path: str):
    try:
        with open(path, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except OSError as e:
        raise ZoxideError(f"could not open database for importing: {path}\n\nCaused by:\n    {os_error_text(e)}")
    imported = import_z(lines) if from_app == 'z' else import_autojump(lines)
    current = load_db()
    if current and not merge:
        raise ZoxideError("current database is not empty, specify --merge to continue anyway")
    if merge:
        m = db_map(current)
        for e in imported:
            if e.path in m:
                m[e.path].score += e.score
                if e.last_accessed > m[e.path].last_accessed:
                    m[e.path].last_accessed = e.last_accessed
            else:
                current.append(e); m[e.path] = e
        entries = current
    else:
        entries = imported
    age_entries(entries)
    save_db(entries)


def parse_float_value(s: str) -> float:
    try:
        return float(s)
    except Exception:
        cli_error(f"invalid value '{s}' for '--score <SCORE>': invalid float literal")
        raise AssertionError


def take_value(args: List[str], i: int, opt: str) -> Tuple[str, int]:
    if i + 1 >= len(args):
        cli_error(f"a value is required for '{opt}' but none was supplied")
    if args[i+1].startswith('-'):
        # clap reports the following token as an unexpected argument.
        unexpected(args[i+1], usage=f"{prog()} add [OPTIONS] <PATHS>...", tip=f"to pass '{args[i+1]}' as a value, use '-- {args[i+1]}'")
    return args[i+1], i + 2


def parse_add(args: List[str]):
    if any(a in ('-h', '--help') for a in args):
        out(sub_help('add')); return
    if any(a in ('-V', '--version') for a in args):
        out(f"zoxide-add {VERSION}"); return
    score = 1.0
    score_seen = False
    paths: List[str] = []
    i = 0; stop = False
    while i < len(args):
        a = args[i]
        if stop:
            paths.append(a); i += 1; continue
        if a == '--':
            stop = True; i += 1; continue
        if a == '--score':
            if score_seen:
                cli_error("the argument '--score <SCORE>' cannot be used multiple times", usage=f"{prog()} add [OPTIONS] <PATHS>...")
            val, i = take_value(args, i, '--score <SCORE>')
            score = parse_float_value(val); score_seen = True; continue
        if a.startswith('--score='):
            if score_seen:
                cli_error("the argument '--score <SCORE>' cannot be used multiple times", usage=f"{prog()} add [OPTIONS] <PATHS>...")
            score = parse_float_value(a.split('=',1)[1]); score_seen=True; i += 1; continue
        if a == '-s':
            if score_seen:
                cli_error("the argument '--score <SCORE>' cannot be used multiple times", usage=f"{prog()} add [OPTIONS] <PATHS>...")
            val, i = take_value(args, i, '--score <SCORE>')
            score = parse_float_value(val); score_seen=True; continue
        if a.startswith('-s=') or (a.startswith('-s') and len(a) > 2):
            if score_seen:
                cli_error("the argument '--score <SCORE>' cannot be used multiple times", usage=f"{prog()} add [OPTIONS] <PATHS>...")
            val = a[3:] if a.startswith('-s=') else a[2:]
            score = parse_float_value(val); score_seen=True; i += 1; continue
        if a.startswith('-'):
            bad = a[:2] if len(a) > 2 and not a.startswith('--') else a
            unexpected(bad, usage=f"{prog()} add [OPTIONS] <PATHS>...", tip=f"to pass '{bad}' as a value, use '-- {bad}'")
        paths.append(a); i += 1
    if not paths:
        cli_error("the following required arguments were not provided:\n  <PATHS>...", usage=f"{prog()} add <PATHS>...")
    add_paths(paths, score)


def parse_remove(args: List[str]):
    if any(a in ('-h', '--help') for a in args):
        out(sub_help('remove')); return
    if any(a in ('-V', '--version') for a in args):
        out(f"zoxide-remove {VERSION}"); return
    paths: List[str] = []
    stop = False
    for a in args:
        if stop:
            paths.append(a); continue
        if a == '--':
            stop = True; continue
        if a.startswith('-'):
            bad = a[:2] if len(a) > 2 and not a.startswith('--') else a
            unexpected(bad, usage=f"{prog()} remove [PATHS]...", tip=f"to pass '{bad}' as a value, use '-- {bad}'")
        paths.append(a)
    remove_paths(paths)


def parse_query(args: List[str]):
    if any(a in ('-h', '--help') for a in args):
        out(sub_help('query')); return
    if any(a in ('-V', '--version') for a in args):
        out(f"zoxide-query {VERSION}"); return
    show_all = False; interactive = False; list_mode = False; with_score = False
    exclude = None; base_dir = None
    keywords: List[str] = []
    i = 0; stop = False
    while i < len(args):
        a = args[i]
        if stop:
            keywords.append(a); i += 1; continue
        if a == '--':
            stop = True; i += 1; continue
        if a == '--all': show_all=True; i += 1; continue
        if a == '--interactive': interactive=True; i += 1; continue
        if a == '--list': list_mode=True; i += 1; continue
        if a == '--score': with_score=True; i += 1; continue
        if a == '--exclude' or a.startswith('--exclude='):
            if a == '--exclude':
                if i+1 >= len(args): cli_error("a value is required for '--exclude <path>' but none was supplied")
                exclude = args[i+1]; i += 2
            else:
                exclude = a.split('=',1)[1]; i += 1
            continue
        if a == '--base-dir' or a.startswith('--base-dir='):
            if a == '--base-dir':
                if i+1 >= len(args): cli_error("a value is required for '--base-dir <path>' but none was supplied")
                base_dir = args[i+1]; i += 2
            else:
                base_dir = a.split('=',1)[1]; i += 1
            continue
        if a.startswith('--'):
            tip = "a similar argument exists: '--base-dir'" if a.startswith('--b') or a == '--bad' else None
            unexpected(a, usage=f"{prog()} query --base-dir <path> [KEYWORDS]..." if tip else f"{prog()} query [OPTIONS] [KEYWORDS]...", tip=tip)
        if a.startswith('-') and len(a) > 1:
            # short flag cluster
            for ch in a[1:]:
                if ch == 'a': show_all=True
                elif ch == 'i': interactive=True
                elif ch == 'l': list_mode=True
                elif ch == 's': with_score=True
                else:
                    unexpected('-'+ch, usage=f"{prog()} query [OPTIONS] [KEYWORDS]...", tip=f"to pass '-{ch}' as a value, use '-- -{ch}'")
            i += 1; continue
        keywords.append(a); i += 1
    if interactive and list_mode:
        # Direction in the error depends on order; approximate is sufficient.
        cli_error("the argument '--interactive' cannot be used with '--list'", usage=f"{prog()} query --interactive" + (" --score" if with_score else "") + " [KEYWORDS]...")
    query_cmd(keywords, show_all, interactive, list_mode, with_score, exclude, base_dir)


def parse_import(args: List[str]):
    if any(a in ('-h', '--help') for a in args):
        out(sub_help('import')); return
    if any(a in ('-V', '--version') for a in args):
        out(f"zoxide-import {VERSION}"); return
    from_app = None; merge = False; pos: List[str] = []
    i = 0; stop = False
    while i < len(args):
        a = args[i]
        if stop:
            pos.append(a); i += 1; continue
        if a == '--': stop=True; i += 1; continue
        if a == '--merge': merge=True; i += 1; continue
        if a == '--from' or a.startswith('--from='):
            if a == '--from':
                if i+1 >= len(args): cli_error("a value is required for '--from <FROM>' but none was supplied")
                from_app = args[i+1]; i += 2
            else:
                from_app = a.split('=',1)[1]; i += 1
            if from_app not in ('autojump','z'):
                cli_error(f"invalid value '{from_app}' for '--from <FROM>'", extra=possible_values(['autojump','z']))
            continue
        if a.startswith('-'):
            unexpected(a, usage=f"{prog()} import [OPTIONS] --from <FROM> <PATH>")
        pos.append(a); i += 1
    if from_app is None:
        cli_error("the following required arguments were not provided:\n  --from <FROM>", usage=f"{prog()} import --from <FROM> <PATH>")
    if not pos:
        cli_error("the following required arguments were not provided:\n  <PATH>", usage=f"{prog()} import --from <FROM> <PATH>")
    if len(pos) > 1:
        unexpected(pos[1], usage=f"{prog()} import [OPTIONS] --from <FROM> <PATH>")
    import_cmd(from_app, merge, pos[0])


def init_output(shell: str, hook: str, no_cmd: bool, cmd: str):
    try:
        import init_data
        text = init_data.get_init_template(shell, hook, no_cmd, os.environ.get('_ZO_ECHO') == '1', os.environ.get('_ZO_RESOLVE_SYMLINKS') == '1')
    except Exception:
        text = ""
    if not no_cmd:
        text = text.replace('__ZO_CMD__', cmd)
    sys.stdout.write(text)


def parse_init(args: List[str]):
    if any(a in ('-h', '--help') for a in args):
        out(sub_help('init')); return
    if any(a in ('-V', '--version') for a in args):
        out(f"zoxide-init {VERSION}"); return
    cmd = 'z'; hook = 'pwd'; no_cmd = False; shell = None
    i = 0
    while i < len(args):
        a = args[i]
        if a == '--no-cmd': no_cmd=True; i += 1; continue
        if a == '--cmd' or a.startswith('--cmd='):
            if a == '--cmd':
                if i+1 >= len(args): cli_error("a value is required for '--cmd <CMD>' but none was supplied")
                cmd = args[i+1]; i += 2
            else:
                cmd = a.split('=',1)[1]; i += 1
            continue
        if a == '--hook' or a.startswith('--hook='):
            if a == '--hook':
                if i+1 >= len(args): cli_error("a value is required for '--hook <HOOK>' but none was supplied")
                hook = args[i+1]; i += 2
            else:
                hook = a.split('=',1)[1]; i += 1
            if hook not in HOOKS:
                cli_error(f"invalid value '{hook}' for '--hook <HOOK>'", extra=possible_values(HOOKS))
            continue
        if a.startswith('-'):
            unexpected(a, usage=f"{prog()} init [OPTIONS] <SHELL>")
        if shell is None:
            shell = a
        else:
            unexpected(a, usage=f"{prog()} init [OPTIONS] <SHELL>")
        i += 1
    if shell is None:
        cli_error("the following required arguments were not provided:\n  <SHELL>", usage=f"{prog()} init <SHELL>")
    if shell not in SHELLS:
        extra = possible_values(SHELLS)
        # clap suggests bash for "bad"; keep a simple suggestion for close-ish values.
        tip = "a similar value exists: 'bash'" if shell else None
        cli_error(f"invalid value '{shell}' for '<SHELL>'", extra=extra, tip=tip)
    init_output(shell, hook, no_cmd, cmd)


def parse_edit(args: List[str]):
    if any(a in ('-h', '--help') for a in args):
        out(sub_help('edit')); return
    if any(a in ('-V', '--version') for a in args):
        out(f"zoxide-edit {VERSION}"); return
    edit_cmd(args)


def dispatch(argv: List[str]):
    if not argv:
        err(main_help())
        raise CliExit(2)
    first = argv[0]
    if first in ('-h', '--help'):
        out(main_help()); return
    if first in ('-V', '--version'):
        out(f"zoxide {VERSION}"); return
    commands = {'add': parse_add, 'edit': parse_edit, 'import': parse_import, 'init': parse_init, 'query': parse_query, 'remove': parse_remove}
    if first not in commands:
        if first == '--':
            err(main_help()); raise CliExit(2)
        if first.startswith('-'):
            unexpected(first, usage=f"{prog()} <COMMAND>")
        cli_error(f"unrecognized subcommand '{first}'", usage=f"{prog()} <COMMAND>")
    commands[first](argv[1:])


def main():
    try:
        dispatch(sys.argv[1:])
    except ZoxideError as e:
        runtime_error(str(e))
    except CliExit as e:
        sys.exit(e.code)

if __name__ == '__main__':
    main()
